/**
 * @suppress
 */
public object FfiConverterTypeEventListener: FfiConverter<EventListener, Long> {
    internal val handleMap = UniffiHandleMap<EventListener>()

    override fun lower(value: EventListener): Long {
        if (value is EventListenerImpl) {
             // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
         } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
         }
    }

    override fun lift(value: Long): EventListener {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return EventListenerImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): EventListener {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: EventListener) = 8UL

    override fun write(value: EventListener, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}


