/**
 * Errors surfaced to foreign code as exceptions.
 */
sealed class GraphrtException: kotlin.Exception() {
    
    /**
     * The runtime configuration JSON is invalid.
     */
    class InvalidConfig(
        
        val `detail`: kotlin.String
        ) : GraphrtException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * The workflow document could not be parsed or compiled.
     */
    class InvalidWorkflow(
        
        val `detail`: kotlin.String
        ) : GraphrtException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * Run inputs, snapshot or selector JSON is invalid.
     */
    class InvalidInput(
        
        val `detail`: kotlin.String
        ) : GraphrtException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * A WebAssembly plugin could not be loaded.
     */
    class Plugin(
        
        val `detail`: kotlin.String
        ) : GraphrtException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * Internal failure (runtime could not start, lock poisoned...).
     */
    class Runtime(
        
        val `detail`: kotlin.String
        ) : GraphrtException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * The capability is not compiled into this build, or not configured.
     */
    class Unsupported(
        
        val `detail`: kotlin.String
        ) : GraphrtException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<GraphrtException> {
        override fun lift(error_buf: RustBuffer.ByValue): GraphrtException = FfiConverterTypeGraphrtError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeGraphrtError : FfiConverterRustBuffer<GraphrtException> {
    override fun read(buf: ByteBuffer): GraphrtException {
        

        return when(buf.getInt()) {
            1 -> GraphrtException.InvalidConfig(
                FfiConverterString.read(buf),
                )
            2 -> GraphrtException.InvalidWorkflow(
                FfiConverterString.read(buf),
                )
            3 -> GraphrtException.InvalidInput(
                FfiConverterString.read(buf),
                )
            4 -> GraphrtException.Plugin(
                FfiConverterString.read(buf),
                )
            5 -> GraphrtException.Runtime(
                FfiConverterString.read(buf),
                )
            6 -> GraphrtException.Unsupported(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: GraphrtException): ULong {
        return when(value) {
            is GraphrtException.InvalidConfig -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is GraphrtException.InvalidWorkflow -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is GraphrtException.InvalidInput -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is GraphrtException.Plugin -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is GraphrtException.Runtime -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is GraphrtException.Unsupported -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
        }
    }

    override fun write(value: GraphrtException, buf: ByteBuffer) {
        when(value) {
            is GraphrtException.InvalidConfig -> {
                buf.putInt(1)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is GraphrtException.InvalidWorkflow -> {
                buf.putInt(2)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is GraphrtException.InvalidInput -> {
                buf.putInt(3)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is GraphrtException.Plugin -> {
                buf.putInt(4)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is GraphrtException.Runtime -> {
                buf.putInt(5)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is GraphrtException.Unsupported -> {
                buf.putInt(6)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



